css:
:where(.wtyg-map-site_china_grain) *{margin:0;padding:0;box-sizing:border-box}
:where(.wtyg-map-site_china_grain){font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif;background:#0a0a0a;color:#fff;overflow:hidden}
:where(.wtyg-map-site_china_grain) :is([data-wtyg-id="map"],#wtyg-noid-map){width:100vw;height:100vh}
:where(.wtyg-map-site_china_grain) .info-panel{position:absolute;top:20px;left:20px;background:rgba(10,10,10,0.95);padding:25px;border-radius:12px;backdrop-filter:blur(10px);box-shadow:0 8px 32px rgba(0,0,0,0.6);z-index:1000;max-width:420px;border:1px solid rgba(255,255,255,0.1)}
:where(.wtyg-map-site_china_grain) .info-panel h1{font-size:24px;margin-bottom:8px;font-weight:700;color:#ffd700}
:where(.wtyg-map-site_china_grain) .info-panel h2{font-size:14px;margin-bottom:15px;color:#aaa;font-weight:400}
:where(.wtyg-map-site_china_grain) .stats{display:grid;gap:12px;margin-top:15px}
:where(.wtyg-map-site_china_grain) .stat-item{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid rgba(255,255,255,0.1)}
:where(.wtyg-map-site_china_grain) .stat-label{color:#888;font-size:13px}
:where(.wtyg-map-site_china_grain) .stat-value{color:#ffd700;font-weight:600;font-size:13px}
:where(.wtyg-map-site_china_grain) .coverage-stat{background:rgba(255,215,0,0.1);padding:15px;border-radius:8px;margin-top:15px;border-left:3px solid #ffd700}
:where(.wtyg-map-site_china_grain) .coverage-label{color:#888;font-size:11px;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:8px}
:where(.wtyg-map-site_china_grain) .coverage-value{font-size:28px;font-weight:700;color:#ffd700}
:where(.wtyg-map-site_china_grain) .coverage-note{color:#aaa;font-size:11px;margin-top:8px;line-height:1.4}
:where(.wtyg-map-site_china_grain) .legend{margin-top:20px;padding-top:15px;border-top:1px solid rgba(255,255,255,0.1)}
:where(.wtyg-map-site_china_grain) .legend-title{font-size:12px;color:#888;margin-bottom:10px;text-transform:uppercase;letter-spacing:0.5px}
:where(.wtyg-map-site_china_grain) .legend-item{display:flex;align-items:center;margin:8px 0;font-size:13px}
:where(.wtyg-map-site_china_grain) .legend-color{width:16px;height:16px;border-radius:50%;margin-right:10px;border:2px solid rgba(255,255,255,0.3)}
:where(.wtyg-map-site_china_grain) .major-depot{background:#ff4444}
:where(.wtyg-map-site_china_grain) .port-terminal{background:#4488ff}
:where(.wtyg-map-site_china_grain) .provincial-depot{background:#ff8844}
:where(.wtyg-map-site_china_grain) .leaflet-popup-content-wrapper{background:rgba(10,10,10,0.98);color:#fff;border-radius:8px;padding:0;box-shadow:0 8px 32px rgba(0,0,0,0.8);border:1px solid rgba(255,255,255,0.2)}
:where(.wtyg-map-site_china_grain) .leaflet-popup-content{margin:0;padding:20px;min-width:280px}
:where(.wtyg-map-site_china_grain) .leaflet-popup-tip{background:rgba(10,10,10,0.98);border:1px solid rgba(255,255,255,0.2)}
:where(.wtyg-map-site_china_grain) .popup-title{font-size:18px;font-weight:700;margin-bottom:12px;color:#ffd700;line-height:1.3}
:where(.wtyg-map-site_china_grain) .popup-detail{margin:8px 0;font-size:13px;line-height:1.6}
:where(.wtyg-map-site_china_grain) .popup-label{color:#888;display:inline-block;width:85px;font-weight:500}
:where(.wtyg-map-site_china_grain) .popup-value{color:#fff}
:where(.wtyg-map-site_china_grain) .popup-capacity{background:rgba(255,215,0,0.1);padding:10px;border-radius:6px;margin-top:12px;border-left:3px solid #ffd700}
:where(.wtyg-map-site_china_grain) .capacity-label{color:#888;font-size:11px;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px}
:where(.wtyg-map-site_china_grain) .capacity-value{font-size:20px;font-weight:700;color:#ffd700}
:where(.wtyg-map-site_china_grain) .popup-type{display:inline-block;padding:4px 10px;border-radius:4px;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-top:10px}
:where(.wtyg-map-site_china_grain) .type-major{background:rgba(255,68,68,0.2);color:#ff4444}
:where(.wtyg-map-site_china_grain) .type-port{background:rgba(68,136,255,0.2);color:#4488ff}
:where(.wtyg-map-site_china_grain) .type-provincial{background:rgba(255,136,68,0.2);color:#ff8844}
:where(.wtyg-map-site_china_grain) .custom-marker{background:none;border:none}
:where(.wtyg-map-site_china_grain) .marker-pin{width:30px;height:30px;border-radius:50% 50% 50% 0;transform:rotate(-45deg);position:relative;animation:pulse 2s infinite}
:where(.wtyg-map-site_china_grain) .marker-pin::after{content:"";width:14px;height:14px;border-radius:50%;background:#fff;position:absolute;top:50%;left:50%;transform:translate(-50%,-50%)}
@keyframes pulse{0%,100%{transform:rotate(-45deg) scale(1);opacity:1}50%{transform:rotate(-45deg) scale(1.1);opacity:0.8}}
@media(max-width:768px){:where(.wtyg-map-site_china_grain) .info-panel{max-width:90%;font-size:12px}}
